/usr/bin/bash -lc "python - <<'PY'
from pathlib import Path
for p in sorted(Path('/work').glob('**/*')):
    if p.is_file() and p.parts[-1] not in {'__pycache__'} and '.pytest_cache' not in p.parts:
        try:
            text=p.read_text()
        except UnicodeDecodeError:
            continue
        print(f'{p.relative_to(\"/work\")}: {len(text.splitlines())}')
PY"

